import BackgroundTasks

BGTaskScheduler.shared.register(forTaskWithIdentifier: "{{task_id}}", using: nil) { task in
    let req = BGAppRefreshTaskRequest(identifier: "{{task_id}}")
    req.earliestBeginDate = Date(timeIntervalSinceNow: {{interval_sec}})
    try? BGTaskScheduler.shared.submit(req)
    Task { await refreshData(); task.setTaskCompleted(success: true) }
}
